sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({ api, helpers }) {
  var instanceURL = api.data.get_instance_url_1.output.fullUrl;
  let html = `
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;700&display=swap');
      .contract-card {
        border-radius: 15px;
        margin: 20px auto;
        padding: 25px;
        // max-width: 520px;
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
        font-family: 'Poppins', sans-serif;
        //transition: transform 0.3s ease, box-shadow 0.3s ease;
        background: white;
        text-align: center;
      }
      .contract-card:hover {
        transform: translateY(-5px);
        box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
      }
      .icon {
        color: #27ae60;
        font-size: 20px;
        margin-right: 8px;
        vertical-align: middle;
      }
      .main-text {
        font-size: 16px;
        font-weight: 500;
        color: #2c3e50;
        line-height: 1.7;
        margin: 0 0 15px 0;
        display: flex;
        align-items: center;
        justify-content: center;
      }
      .load-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 5px;
        padding: 5px 15px; /* Smaller button */
        background-color: #0052cc; /* Matching color */
        color: white;
        border: none;
        border-radius: 3px; /* Slightly rounded corners */
        font-family: 'Poppins', sans-serif;
        font-size: 13px;
        font-weight: 500;
        text-decoration: none;
        text-align: center;
        transition: background-color 0.3s ease;
      }
      .load-button:hover {
        background-color: #003f99;
      }
      .upload-icon {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 18px; /* Size of the circle */
        height: 18px;
        background-color: #0052cc; /* Blue background to match the button */
        border-radius: 50%; /* Circular shape */
        color: white; /* White arrow */
        font-size: 12px; /* Adjust arrow size */
        margin-right: 5px; /* Space between icon and text */
        vertical-align: middle;
      }
      @media (max-width: 768px) {
        .contract-card {
          margin: 15px;
          padding: 20px;
          max-width: 90%;
        }
        .main-text {
          font-size: 15px;
        }
        .load-button {
          padding: 4px 12px;
          font-size: 12px;
        }
        .upload-icon {
          width: 16px;
          height: 16px;
          font-size: 10px;
        }
      }
    </style>
    <div class="contract-card">
      <div class="card-content">
        <p class="main-text">
          <span class="icon">✅</span> Import contracts to efficiently manage your software agreements, monitor renewal dates, and maintain licensing compliance.
        </p>
        <a href="${instanceURL}/now/nav/ui/classic/params/target/%24guided_setup.do%23%2Fcontent%2F2b09b6b0c3579a100ced12f1b40131bf%3Ffocus%3Dcc7bbaf0c3579a100ced12f1b4013185%26group_focuses%3D%26home_options%3Ddashboard%26scroll_to%3D%26filter%3Dall" target="_blank" class="load-button">
          <span class="upload-icon">⇧</span> Load Contract 
        </a>
      </div>
    </div>
  `;

  return html;
}
